/**
 * ScriptInterpreter Module
 * 
 * This module parses raw JavaScript code related to a component and structures it into a class-friendly format.
 * It organizes global variables, methods, function calls, and event listeners for subsequent compilation steps.
 */

const acorn = require('acorn');
const walk = require('acorn-walk');

/**
 * Class representing a Script Interpreter.
 */
class ScriptInterpreter {
  /**
   * Create a ScriptInterpreter.
   */
  constructor() {
    this.globalVariables = [];
    this.methods = [];
    this.calls = [];
    this.eventListeners = [];
    this.scriptContent = '';
    this.uniqueMethodCounter = 1;
  }

  /**
   * Interpret the provided JavaScript code and extract class components.
   * 
   * @param {string} scriptContent - The raw JavaScript code to interpret.
   * @returns {Object} An object containing extracted global variables, methods, calls, and event listeners.
   * @throws Will throw an error if parsing fails or if a class is detected.
   */
  interpret(scriptContent) {
    this.scriptContent = scriptContent;
    this.globalVariables = [];
    this.methods = [];
    this.calls = [];
    this.eventListeners = [];
    this.uniqueMethodCounter = 1;

    try {
      const ast = acorn.parse(this.scriptContent, {
        ecmaVersion: 'latest',
        sourceType: 'script',
        locations: false,
      });

      // Check for class declarations and expressions
      walk.simple(ast, {
        ClassDeclaration: () => {
          throw new Error('Classes are not supported.');
        },
        ClassExpression: () => {
          throw new Error('Classes are not supported.');
        }
      });

      this.processAst(ast);
      return {
        variables: this.globalVariables,
        methods: this.methods,
        calls: this.calls,
        eventListeners: this.eventListeners,
      };
    } catch (error) {
      throw new Error(`Failed to interpret script: ${error.message}`);
    }
  }

  /**
   * Process the Abstract Syntax Tree (AST) to extract class components.
   * 
   * @param {Object} ast - The AST generated by Acorn.
   */
  processAst(ast) {
    // Only process top-level nodes (global scope)
    ast.body.forEach(node => {
      if (node.type === 'VariableDeclaration') {
        this.processVariableDeclaration(node);
      } else if (node.type === 'FunctionDeclaration') {
        this.processFunctionDeclaration(node);
      } else if (node.type === 'ExpressionStatement') {
        this.processExpressionStatement(node);
      } else if (node.type === 'ImportDeclaration') {
        this.processImportDeclaration(node);
      } else {
        // Ignore other top-level constructs or handle as needed
      }
    });
