  /**
   * Process import declarations and treat them as global variables.
   * 
   * @param {Object} node - The ImportDeclaration node.
   */
  processImportDeclaration(node) {
    const code = this.generateCode(node);
    this.globalVariables.push(`${code};`);
  }

  /**
   * Process variable declarations in the global scope.
   * 
   * @param {Object} node - The VariableDeclaration node.
   */
  processVariableDeclaration(node) {
    node.declarations.forEach((decl) => {
      if (decl.init && (decl.init.type === 'ArrowFunctionExpression' || decl.init.type === 'FunctionExpression')) {
        this.processFunctionExpression(decl, node.kind);
      } else {
        this.processGlobalVariable(decl, node.kind);
      }
    });
