  /**
   * Process a single global variable declaration.
   * 
   * @param {Object} decl - The VariableDeclarator node.
   * @param {string} kind - The kind of variable declaration (var, let, const).
   */
  processGlobalVariable(decl, kind) {
    const name = decl.id.name;
    const init = decl.init ? this.generateCode(decl.init) : 'undefined';
    this.globalVariables.push(`${kind} ${name} = ${init};`);
  }

