    const name = decl.id.name;
    const params = decl.init.params.map(param => this.generateCode(param)).join(', ');
    let methodString = '';

    if (decl.init.type === 'FunctionExpression' || decl.init.type === 'ArrowFunctionExpression') {
      if (decl.init.body.type === 'BlockStatement') {
        const body = this.generateCode(decl.init.body).trim();
        methodString = `${name}(${params}) ${body}`;
      } else {
        // Concise arrow function
        const expression = this.generateCode(decl.init.body).trim();
        methodString = `${name}(${params}) { return ${expression}; }`;
