  processImmediateFunction(expression) {
    const name = this.generateUniqueMethodName('immediateFunction');
    let params = '';
    let args = '';
    let body = '';

    if (expression.callee.type === 'FunctionExpression' || expression.callee.type === 'ArrowFunctionExpression') {
