    current_file: usize,
    total_files: usize,
    file_name: String,
    downloaded_bytes: u64,
    total_bytes: u64,
}

#[derive(Serialize, Clone)]
struct DownloadStatus {
    status: String,
    additional_info: Option<String>,
}

fn get_exe_dir() -> PathBuf {
    std::env::current_exe().unwrap().parent().unwrap().to_path_buf()
}

async fn dir_exists(path: &Path) -> Result<bool, std::io::Error> {
    match fs::metadata(path).await {
        Ok(metadata) => Ok(metadata.is_dir()),
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(err) => Err(err),
    }
}

async fn read_patch_file(path: &Path) -> Result<Vec<PatchEntry>, String> {
    let content = fs::read_to_string(path).await.map_err(|e| e.to_string())?;
    let patches: Vec<PatchEntry> = serde_json::from_str(&content).map_err(|e| e.to_string())?;
    Ok(patches)
}

async fn emit_download_status(app_handle: &AppHandle, status: &str, additional_info: Option<String>,) -> Result<(), String> {
    app_handle.emit("download_status", DownloadStatus {status: status.to_string(), additional_info,}).map_err(|e| e.to_string())
}

async fn download_file(app_handle: &AppHandle, client: &Client, entry: &PatchEntry, download_dir: &Path, current_file: usize, total_files: usize,) -> Result<(), String> {
    let url = format!("https://hil-speed.hetzner.com/{}", entry.file_name);
    let file_path = download_dir.join(&entry.file_name);

    let mut response = client.get(&url).send().await.map_err(|e| e.to_string())?;
    if !response.status().is_success() {
        return Err(format!("Falha ao baixar '{}': HTTP {}", entry.file_name, response.status()));
    }

    let total_bytes = response.content_length().unwrap_or(0);
    let mut file = fs::File::create(&file_path).await.map_err(|e| e.to_string())?;

    let mut downloaded_bytes = 0u64;
    let start_time = Instant::now();

    emit_download_status(app_handle, "Downloading", None).await?;

    let mut last_emit_time = Instant::now();

    while let Some(chunk) = response.chunk().await.map_err(|e| e.to_string())? {
        file.write_all(&chunk).await.map_err(|e| e.to_string())?;
        downloaded_bytes += chunk.len() as u64;

        let now = Instant::now();
        if now.duration_since(last_emit_time) >= Duration::from_millis(100) {
            let elapsed = start_time.elapsed().as_secs_f64();
            let speed = if elapsed > 0.0 {
                downloaded_bytes as f64 / elapsed
            } else {
                0.0
            };

            app_handle.emit("download_info", DownloadInfo {
                current_file,
                total_files,
                file_name: entry.file_name.clone(),
                downloaded_bytes,
                total_bytes,
            }).map_err(|e| e.to_string())?;
            app_handle.emit("download_speed", speed).map_err(|e| e.to_string())?;
            last_emit_time = now;
        }
    }

    Ok(())
}

